export const AdditiveExtractionSchema = z.object({
  memory: z.array(
    z.object({
      id: z.string(),
      text: z.string(),
      attributed_to: z.enum(["user", "assistant"]).optional(),
      linked_memory_ids: z.array(z.string()).optional(),
    }),
  ),
});

