  ScalarQuantizationCompression,
  BinaryQuantizationCompression,
  VectorizedQuery,
} from "@azure/search-documents";
import { DefaultAzureCredential } from "@azure/identity";
import { VectorStore } from "./base";
import { SearchFilters, VectorStoreConfig, VectorStoreResult } from "../types";

/**
 * Configuration interface for Azure AI Search vector store
 */
interface AzureAISearchConfig extends VectorStoreConfig {
  /**
   * Azure AI Search service name (e.g., "my-search-service")
   */
  serviceName: string;

  /**
   * Index/collection name to use
   */
  collectionName: string;

  /**
   * API key for authentication (if not provided, uses DefaultAzureCredential)
   */
  apiKey?: string;

  /**
   * Vector embedding dimensions
   */
  embeddingModelDims: number;

  /**
   * Compression type: 'none', 'scalar', or 'binary'
   * @default 'none'
   */
  compressionType?: "none" | "scalar" | "binary";

  /**
   * Use half precision (float16) instead of full precision (float32)
   * @default false
   */
  useFloat16?: boolean;

  /**
   * Enable hybrid search (combines vector + text search)
   * @default false
   */
  hybridSearch?: boolean;

  /**
   * Vector filter mode: 'preFilter' or 'postFilter'
   * @default 'preFilter'
   */
  vectorFilterMode?: string;
}

/**
 * Azure AI Search vector store implementation
 * Supports vector search with hybrid search, compression, and filtering
 */
export class AzureAISearch implements VectorStore {
  private searchClient: SearchClient<any>;
  private indexClient: SearchIndexClient;
  private readonly serviceName: string;
  private readonly indexName: string;
  private readonly embeddingModelDims: number;
  private readonly compressionType: "none" | "scalar" | "binary";
  private readonly useFloat16: boolean;
  private readonly hybridSearch: boolean;
  private readonly vectorFilterMode: string;
  private readonly apiKey: string | undefined;
  private _initPromise?: Promise<void>;

  constructor(config: AzureAISearchConfig) {
    this.serviceName = config.serviceName;
    this.indexName = config.collectionName;
    this.embeddingModelDims = config.embeddingModelDims;
    this.compressionType = config.compressionType || "none";
    this.useFloat16 = config.useFloat16 || false;
    this.hybridSearch = config.hybridSearch || false;
    this.vectorFilterMode = config.vectorFilterMode || "preFilter";
    this.apiKey = config.apiKey;

    const serviceEndpoint = `https://${this.serviceName}.search.windows.net`;

    // Determine authentication: API key or DefaultAzureCredential
    const credential =
      this.apiKey && this.apiKey !== "" && this.apiKey !== "your-api-key"
        ? new AzureKeyCredential(this.apiKey)
        : new DefaultAzureCredential();

    // Initialize clients
    this.searchClient = new SearchClient(
      serviceEndpoint,
      this.indexName,
      credential,
    );

    this.indexClient = new SearchIndexClient(serviceEndpoint, credential);

    // Initialize the index
    this.initialize().catch(console.error);
  }

  /**
   * Initialize the Azure AI Search index if it doesn't exist
   */
  async initialize(): Promise<void> {
    if (!this._initPromise) {
      this._initPromise = this._doInitialize();
    }
    return this._initPromise;
  }

  private async _doInitialize(): Promise<void> {
    try {
      const collections = await this.listCols();
      if (!collections.includes(this.indexName)) {
        await this.createCol();
      }
    } catch (error) {
      console.error("Error initializing Azure AI Search:", error);
      throw error;
    }
  }

  /**
   * Create a new index in Azure AI Search
   */
  private async createCol(): Promise<void> {
    // Determine vector type based on use_float16 setting
    const vectorType = this.useFloat16
      ? "Collection(Edm.Half)"
      : "Collection(Edm.Single)";

    // Configure compression settings
    const compressionConfigurations: Array<
      ScalarQuantizationCompression | BinaryQuantizationCompression
    > = [];
    let compressionName: string | undefined = undefined;

    if (this.compressionType === "scalar") {
      compressionName = "myCompression";
      compressionConfigurations.push({
        kind: "scalarQuantization",
        compressionName: compressionName,
      } as ScalarQuantizationCompression);
    } else if (this.compressionType === "binary") {
      compressionName = "myCompression";
      compressionConfigurations.push({
        kind: "binaryQuantization",
        compressionName: compressionName,
      } as BinaryQuantizationCompression);
    }

    // Define index fields
    const fields: SearchField[] = [
      {
        name: "id",
        type: "Edm.String",
        key: true,
      } as SimpleField,
      {
        name: "user_id",
        type: "Edm.String",
        filterable: true,
      } as SimpleField,
      {
        name: "run_id",
        type: "Edm.String",
        filterable: true,
      } as SimpleField,
      {
        name: "agent_id",
        type: "Edm.String",
        filterable: true,
      } as SimpleField,
      {
        name: "vector",
        type: vectorType as SearchFieldDataType,
        searchable: true,
        vectorSearchDimensions: this.embeddingModelDims,
        vectorSearchProfileName: "my-vector-config",
      } as SearchField,
      {
        name: "payload",
        type: "Edm.String",
        searchable: true,
      } as SearchField,
    ];

    // Configure vector search
    const vectorSearch: VectorSearch = {
      profiles: [
        {
          name: "my-vector-config",
          algorithmConfigurationName: "my-algorithms-config",
          compressionName:
            this.compressionType !== "none" ? compressionName : undefined,
        } as VectorSearchProfile,
      ],
      algorithms: [
        {
          kind: "hnsw",
          name: "my-algorithms-config",
        } as HnswAlgorithmConfiguration,
      ],
      compressions: compressionConfigurations,
    };

    // Create index
    const index: SearchIndex = {
      name: this.indexName,
      fields,
      vectorSearch,
    };

    await this.indexClient.createOrUpdateIndex(index);
  }

  /**
   * Generate a document for insertion
   */
  private generateDocument(
    vector: number[],
    payload: Record<string, any>,
    id: string,
  ): Record<string, any> {
    const document: Record<string, any> = {
      id,
      vector,
      payload: JSON.stringify(payload),
    };

    // Extract additional fields if they exist
    for (const field of ["user_id", "run_id", "agent_id"]) {
      if (field in payload) {
        document[field] = payload[field];
      }
    }

    return document;
  }

  /**
   * Insert vectors into the index
   */
  async insert(
    vectors: number[][],
    ids: string[],
    payloads: Record<string, any>[],
  ): Promise<void> {
    console.log(
      `Inserting ${vectors.length} vectors into index ${this.indexName}`,
    );

    const documents = vectors.map((vector, idx) =>
      this.generateDocument(vector, payloads[idx] || {}, ids[idx]),
    );

    const response = await this.searchClient.uploadDocuments(documents);

    // Check for errors
    for (const result of response.results) {
      if (!result.succeeded) {
        throw new Error(
          `Insert failed for document ${result.key}: ${result.errorMessage}`,
        );
      }
    }
  }

  /**
   * Sanitize filter keys to remove non-alphanumeric characters
   */
  private sanitizeKey(key: string): string {
    return key.replace(/[^\w]/g, "");
  }

  /**
   * Build OData filter expression from SearchFilters
   */
  private buildFilterExpression(filters: SearchFilters): string {
    const filterConditions: string[] = [];

    for (const [key, value] of Object.entries(filters)) {
      const safeKey = this.sanitizeKey(key);

      if (typeof value === "string") {
        // Escape single quotes in string values
        const safeValue = value.replace(/'/g, "''");
        filterConditions.push(`${safeKey} eq '${safeValue}'`);
      } else {
        filterConditions.push(`${safeKey} eq ${value}`);
      }
    }

    return filterConditions.join(" and ");
  }

  /**
   * Extract JSON from payload string
   * Handles cases where payload might have extra text
   */
  private extractJson(payload: string): string {
    try {
      // Try to parse as-is first
      JSON.parse(payload);
      return payload;
    } catch {
      // If that fails, try to extract JSON object
      const match = payload.match(/\{.*\}/s);
      return match ? match[0] : payload;
    }
  }

  /**
   * Keyword search using Azure AI Search native full-text (BM25) capabilities
   */
  async keywordSearch(
    query: string,
    topK: number = 5,
    filters?: SearchFilters,
  ): Promise<VectorStoreResult[] | null> {
    try {
      const filterExpression = filters
        ? this.buildFilterExpression(filters)
        : undefined;

      const searchResults = await this.searchClient.search(query, {
        filter: filterExpression,
        top: topK,
        searchFields: ["payload"],
      });

      const results: VectorStoreResult[] = [];

      for await (const result of searchResults.results) {
        const payloadStr = result.document.payload as string;
        const payload = JSON.parse(this.extractJson(payloadStr));

        results.push({
          id: result.document.id as string,
          score: result.score,
          payload,
        });
      }

      return results;
    } catch (error) {
      console.error("Error during keyword search:", error);
      return null;
    }
  }

  /**
   * Search for similar vectors
   */
  async search(
    query: number[],
    topK: number = 5,
    filters?: SearchFilters,
  ): Promise<VectorStoreResult[]> {
    const filterExpression = filters
      ? this.buildFilterExpression(filters)
      : undefined;

    const vectorQuery: VectorizedQuery<any> = {
      kind: "vector",
      vector: query,
      kNearestNeighborsCount: topK,
      fields: ["vector"],
    };

    let searchResults;

    if (this.hybridSearch) {
      // Hybrid search: combines vector + text search
      searchResults = await this.searchClient.search("*", {
        vectorSearchOptions: {
          queries: [vectorQuery],
          filterMode: this.vectorFilterMode as any,
        },
        filter: filterExpression,
        top: topK,
        searchFields: ["payload"],
      });
    } else {
      // Pure vector search
      searchResults = await this.searchClient.search("*", {
        vectorSearchOptions: {
          queries: [vectorQuery],
          filterMode: this.vectorFilterMode as any,
        },
        filter: filterExpression,
        top: topK,
      });
    }

    const results: VectorStoreResult[] = [];

    for await (const result of searchResults.results) {
      const payloadStr = result.document.payload as string;
      const payload = JSON.parse(this.extractJson(payloadStr));

      results.push({
        id: result.document.id as string,
        score: result.score,
        payload,
      });
    }

    return results;
  }

  /**
   * Delete a vector by ID
   */
  async delete(vectorId: string): Promise<void> {
    const response = await this.searchClient.deleteDocuments([
      { id: vectorId },
    ]);

    for (const result of response.results) {
      if (!result.succeeded) {
        throw new Error(
          `Delete failed for document ${vectorId}: ${result.errorMessage}`,
        );
      }
    }

    console.log(
      `Deleted document with ID '${vectorId}' from index '${this.indexName}'.`,
    );
  }

  /**
   * Update a vector and its payload
   */
  async update(
    vectorId: string,
    vector: number[],
    payload: Record<string, any>,
  ): Promise<void> {
    const document: Record<string, any> = { id: vectorId };

    if (vector) {
      document.vector = vector;
    }

    if (payload) {
      document.payload = JSON.stringify(payload);

      // Extract additional fields
      for (const field of ["user_id", "run_id", "agent_id"]) {
        if (field in payload) {
          document[field] = payload[field];
        }
      }
    }

    const response = await this.searchClient.mergeOrUploadDocuments([document]);

    for (const result of response.results) {
      if (!result.succeeded) {
        throw new Error(
          `Update failed for document ${vectorId}: ${result.errorMessage}`,
        );
      }
    }
  }

  /**
   * Retrieve a vector by ID
   */
  async get(vectorId: string): Promise<VectorStoreResult | null> {
    try {
      const result = await this.searchClient.getDocument(vectorId);
      const payloadStr = result.payload as string;
      const payload = JSON.parse(this.extractJson(payloadStr));

      return {
        id: result.id as string,
        payload,
      };
    } catch (error: any) {
      // Return null if document not found
      if (error?.statusCode === 404) {
        return null;
      }
      throw error;
    }
  }

  /**
   * List all collections (indexes)
   */
  private async listCols(): Promise<string[]> {
    const names: string[] = [];

    for await (const index of this.indexClient.listIndexes()) {
      names.push(index.name);
    }

    return names;
  }

  /**
   * Delete the index
   */
  async deleteCol(): Promise<void> {
    await this.indexClient.deleteIndex(this.indexName);
  }

  /**
   * Get information about the index
   */
  private async colInfo(): Promise<{ name: string; fields: SearchField[] }> {
    const index = await this.indexClient.getIndex(this.indexName);
    return {
      name: index.name,
      fields: index.fields,
    };
  }

  /**
   * List all vectors in the index
   */
  async list(
    filters?: SearchFilters,
    topK: number = 100,
  ): Promise<[VectorStoreResult[], number]> {
    const filterExpression = filters
      ? this.buildFilterExpression(filters)
      : undefined;

    const searchResults = await this.searchClient.search("*", {
      filter: filterExpression,
      top: topK,
    });

    const results: VectorStoreResult[] = [];

    for await (const result of searchResults.results) {
      const payloadStr = result.document.payload as string;
      const payload = JSON.parse(this.extractJson(payloadStr));

      results.push({
        id: result.document.id as string,
        score: result.score,
        payload,
      });
    }

    return [results, results.length];
  }

  /**
   * Generate a random user ID
   */
  private generateUUID(): string {
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(
      /[xy]/g,
      function (c) {
        const r = (Math.random() * 16) | 0;
        const v = c === "x" ? r : (r & 0x3) | 0x8;
        return v.toString(16);
      },
    );
  }

  /**
   * Get user ID from memory_migrations collection
   * Required by VectorStore interface
   */
  async getUserId(): Promise<string> {
    try {
      // Check if memory_migrations index exists
      const collections = await this.listCols();
      const migrationIndexExists = collections.includes("memory_migrations");

      if (!migrationIndexExists) {
        // Create memory_migrations index
        const migrationIndex: SearchIndex = {
          name: "memory_migrations",
          fields: [
            {
              name: "id",
              type: "Edm.String",
              key: true,
            } as SimpleField,
            {
              name: "user_id",
              type: "Edm.String",
              searchable: false,
              filterable: true,
            } as SimpleField,
          ],
        };
        await this.indexClient.createOrUpdateIndex(migrationIndex);
      }

      // Try to get existing user_id
      const searchResults = await this.searchClient.search("*", {
        top: 1,
      });

      for await (const result of searchResults.results) {
        const userId = result.document.user_id as string;
        if (userId) {
          return userId;
        }
      }

      // Generate a random user_id if none exists
      const randomUserId =
        Math.random().toString(36).substring(2, 15) +
        Math.random().toString(36).substring(2, 15);

      await this.searchClient.uploadDocuments([
        {
          id: this.generateUUID(),
          user_id: randomUserId,
        },
      ]);

      return randomUserId;
    } catch (error) {
      console.error("Error getting user ID:", error);
      throw error;
    }
  }

  /**
   * Set user ID in memory_migrations collection
   * Required by VectorStore interface
   */
  async setUserId(userId: string): Promise<void> {
    try {
      // Get existing point ID or generate new one
      const searchResults = await this.searchClient.search("*", {
        top: 1,
      });

      let pointId = this.generateUUID();

      for await (const result of searchResults.results) {
        pointId = result.document.id as string;
        break;
      }

      await this.searchClient.mergeOrUploadDocuments([
        {
          id: pointId,
          user_id: userId,
        },
      ]);
    } catch (error) {
      console.error("Error setting user ID:", error);
      throw error;
    }
  }

  /**
   * Reset the index by deleting and recreating it
   */
  async reset(): Promise<void> {
    console.log(`Resetting index ${this.indexName}...`);

    try {
      // Delete the index
      await this.deleteCol();

      // Recreate the index
      await this.createCol();
    } catch (error) {
      console.error(`Error resetting index ${this.indexName}:`, error);
      throw error;
    }
  }
}
","import type { Client as ClientType } from "pg";
import pkg from "pg";
const { Client, escapeIdentifier } = pkg;
import { VectorStore } from "./base";
import { SearchFilters, VectorStoreConfig, VectorStoreResult } from "../types";

const SAFE_IDENTIFIER_RE = /^[a-zA-Z_][a-zA-Z0-9_]{0,127}$/;

function validateIdentifier(
  name: string,
  label: string = "identifier",
): string {
  if (!SAFE_IDENTIFIER_RE.test(name)) {
    throw new Error(
      `Invalid ${label} '${name}': only letters, digits, and underscores are allowed, ` +
        `must start with a letter or underscore, and be at most 128 characters.`,
    );
  }
  return name;
}

function escapeFilterKey(key: string): string {
  if (!SAFE_IDENTIFIER_RE.test(key)) {
    throw new Error(
      `Invalid filter key '${key}': only letters, digits, and underscores are allowed.`,
    );
  }
  return key;
}

interface FilterResult {
  conditions: string[];
  values: any[];
  paramIndex: number;
}

const OPERATOR_SQL_MAP: Record<string, { template: string; numeric: boolean }> =
  {
    eq: { template: "payload->>'%KEY%' = $%IDX%", numeric: false },
    ne: { template: "payload->>'%KEY%' != $%IDX%", numeric: false },
    gt: { template: "(payload->>'%KEY%')::numeric > $%IDX%", numeric: true },
    gte: { template: "(payload->>'%KEY%')::numeric >= $%IDX%", numeric: true },
    lt: { template: "(payload->>'%KEY%')::numeric < $%IDX%", numeric: true },
    lte: { template: "(payload->>'%KEY%')::numeric <= $%IDX%", numeric: true },
    in: { template: "payload->>'%KEY%' = ANY($%IDX%::text[])", numeric: false },
    nin: {
      template: "NOT (payload->>'%KEY%' = ANY($%IDX%::text[]))",
      numeric: false,
    },
    contains: {
      template: "payload->>'%KEY%' LIKE $%IDX% ESCAPE '\\'",
      numeric: false,
    },
    icontains: {
      template: "payload->>'%KEY%' ILIKE $%IDX% ESCAPE '\\'",
      numeric: false,
    },
  };

export function buildFilterConditions(
  filters: Record<string, any> | undefined,
  startIndex: number,
): FilterResult {
  const conditions: string[] = [];
  const values: any[] = [];
  let paramIndex = startIndex;

  if (!filters) {
    return { conditions, values, paramIndex };
  }

  for (const [key, value] of Object.entries(filters)) {
    if (key === "$or") {
      const orGroups: string[] = [];
      for (const orFilter of value as Record<string, any>[]) {
        const sub = buildFilterConditions(orFilter, paramIndex);
        if (sub.conditions.length > 0) {
          orGroups.push("(" + sub.conditions.join(" AND ") + ")");
          values.push(...sub.values);
          paramIndex = sub.paramIndex;
        }
      }
      if (orGroups.length > 0) {
        conditions.push("(" + orGroups.join(" OR ") + ")");
      }
      continue;
    }

    if (key === "$not") {
      const notGroups: string[] = [];
      for (const notFilter of value as Record<string, any>[]) {
        const sub = buildFilterConditions(notFilter, paramIndex);
        if (sub.conditions.length > 0) {
          notGroups.push("(" + sub.conditions.join(" AND ") + ")");
          values.push(...sub.values);
          paramIndex = sub.paramIndex;
        }
      }
      if (notGroups.length > 0) {
        conditions.push("NOT (" + notGroups.join(" OR ") + ")");
      }
      continue;
    }

    const safeKey = escapeFilterKey(key);

    if (value === "*") {
      conditions.push(`payload ? $${paramIndex}`);
      values.push(key);
      paramIndex++;
      continue;
    }

    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      for (const [op, opValue] of Object.entries(value)) {
        const mapping = OPERATOR_SQL_MAP[op];
        if (!mapping) {
          throw new Error(`Unsupported filter operator: ${op}`);
        }
        const clause = mapping.template
          .replace("%KEY%", safeKey)
          .replace("%IDX%", String(paramIndex));
        conditions.push(clause);

        if (op === "in" || op === "nin") {
          values.push((opValue as any[]).map(String));
        } else if (op === "contains" || op === "icontains") {
          const escaped = String(opValue)
            .replace(/\\/g, "\\\\")
            .replace(/%/g, "\\%")
            .replace(/_/g, "\\_");
          values.push(`%${escaped}%`);
        } else if (mapping.numeric) {
          values.push(Number(opValue));
        } else {
          values.push(String(opValue));
        }
        paramIndex++;
      }
    } else if (Array.isArray(value)) {
      conditions.push(`payload->>'${safeKey}' = ANY($${paramIndex}::text[])`);
      values.push(value.map(String));
      paramIndex++;
    } else {
      conditions.push(`payload->>'${safeKey}' = $${paramIndex}`);
      if (typeof value === "boolean") {
        values.push(JSON.stringify(value));
      } else {
        values.push(String(value));
      }
      paramIndex++;
    }
  }

  return { conditions, values, paramIndex };
}

interface PGVectorConfig extends VectorStoreConfig {
  dbname?: string;
  user: string;
  password: string;
  host: string;
  port: number;
  embeddingModelDims: number;
  diskann?: boolean;
  hnsw?: boolean;
}

export class PGVector implements VectorStore {
  private client: ClientType;
  private collectionName: string;
  private useDiskann: boolean;
  private useHnsw: boolean;
  private readonly dbName: string;
  private config: PGVectorConfig;
  private _initPromise?: Promise<void>;

  constructor(config: PGVectorConfig) {
    this.collectionName = validateIdentifier(
      config.collectionName || "memories",
      "collectionName",
    );
    this.useDiskann = config.diskann || false;
    this.useHnsw = config.hnsw || false;
    this.dbName = validateIdentifier(config.dbname || "vector_store", "dbname");
    this.config = config;

    this.client = new Client({
      database: "postgres", // Initially connect to default postgres database
      user: config.user,
      password: config.password,
      host: config.host,
      port: config.port,
    });
    this.initialize().catch(console.error);
  }

  private col(): string {
    return escapeIdentifier(this.collectionName);
  }

  async initialize(): Promise<void> {
    if (!this._initPromise) {
      this._initPromise = this._doInitialize();
    }
    return this._initPromise;
  }

  private async _doInitialize(): Promise<void> {
    try {
      await this.client.connect();

      // Check if database exists
      const dbExists = await this.checkDatabaseExists(this.dbName);
      if (!dbExists) {
        await this.createDatabase(this.dbName);
      }

      // Disconnect from postgres database
      await this.client.end();

      // Connect to the target database
      this.client = new Client({
        database: this.dbName,
        user: this.config.user,
        password: this.config.password,
        host: this.config.host,
        port: this.config.port,
      });
      await this.client.connect();

      // Create vector extension
      await this.client.query("CREATE EXTENSION IF NOT EXISTS vector");

      // Create memory_migrations table
      await this.client.query(`
        CREATE TABLE IF NOT EXISTS memory_migrations (
          id SERIAL PRIMARY KEY,
          user_id TEXT NOT NULL UNIQUE
        )
      `);

      // Check if the collection exists
      const collections = await this.listCols();
      if (!collections.includes(this.collectionName)) {
        await this.createCol(this.config.embeddingModelDims);
      }
    } catch (error) {
      console.error("Error during initialization:", error);
      throw error;
    }
  }

  private async checkDatabaseExists(dbName: string): Promise<boolean> {
    const result = await this.client.query(
      "SELECT 1 FROM pg_database WHERE datname = $1",
      [dbName],
    );
    return result.rows.length > 0;
  }

  private async createDatabase(dbName: string): Promise<void> {
    await this.client.query(`CREATE DATABASE ${escapeIdentifier(dbName)}`);
  }

  private async createCol(embeddingModelDims: number): Promise<void> {
    const dims = Math.floor(embeddingModelDims);
    await this.client.query(`
      CREATE TABLE IF NOT EXISTS ${this.col()} (
        id UUID PRIMARY KEY,
        vector vector(${dims}),
        payload JSONB
      );
    `);

    if (this.useDiskann && embeddingModelDims < 2000) {
      try {
        const result = await this.client.query(
          "SELECT * FROM pg_extension WHERE extname = 'vectorscale'",
        );
        if (result.rows.length > 0) {
          await this.client.query(`
            CREATE INDEX IF NOT EXISTS ${escapeIdentifier(this.collectionName + "_diskann_idx")}
            ON ${this.col()}
            USING diskann (vector);
          `);
        }
      } catch (error) {
        console.warn("DiskANN index creation failed:", error);
      }
    } else if (this.useHnsw) {
      try {
        await this.client.query(`
          CREATE INDEX IF NOT EXISTS ${escapeIdentifier(this.collectionName + "_hnsw_idx")}
          ON ${this.col()}
          USING hnsw (vector vector_cosine_ops);
        `);
      } catch (error) {
        console.warn("HNSW index creation failed:", error);
      }
    }
  }

  async insert(
    vectors: number[][],
    ids: string[],
    payloads: Record<string, any>[],
  ): Promise<void> {
    const values = vectors.map((vector, i) => ({
      id: ids[i],
      vector: `[${vector.join(",")}]`,
      payload: payloads[i],
    }));

    const query = `
      INSERT INTO ${this.col()} (id, vector, payload)
      VALUES ($1, $2::vector, $3::jsonb)
    `;

    await Promise.all(
      values.map((value) =>
        this.client.query(query, [value.id, value.vector, value.payload]),
      ),
    );
  }

  async keywordSearch(
    query: string,
    topK: number = 5,
    filters?: SearchFilters,
  ): Promise<VectorStoreResult[] | null> {
    try {
      const {
        conditions,
        values,
        paramIndex: _,
      } = buildFilterConditions(filters, 3);
      const filterValues: any[] = [query, topK, ...values];

      const filterClause =
        conditions.length > 0 ? "AND " + conditions.join(" AND ") : "";

      const searchQuery = `
        SELECT id, ts_rank_cd(to_tsvector('simple', payload->>'textLemmatized'), plainto_tsquery('simple', $1)) AS score, payload
        FROM ${this.col()}
        WHERE to_tsvector('simple', payload->>'textLemmatized') @@ plainto_tsquery('simple', $1)
        ${filterClause}
        ORDER BY score DESC
        LIMIT $2
      `;

      const result = await this.client.query(searchQuery, filterValues);

      return result.rows.map((row) => ({
        id: row.id,
        payload: row.payload,
        score: row.score,
      }));
    } catch (error) {
      console.error("Error during keyword search:", error);
      return null;
    }
  }

  async search(
    query: number[],
    topK: number = 5,
    filters?: SearchFilters,
  ): Promise<VectorStoreResult[]> {
    const queryVector = `[${query.join(",")}]`;
    const {
      conditions,
      values,
      paramIndex: _,
    } = buildFilterConditions(filters, 3);
    const filterValues: any[] = [queryVector, topK, ...values];

    const filterClause =
      conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";

    const searchQuery = `
      SELECT id, vector <=> $1::vector AS distance, payload
      FROM ${this.col()}
      ${filterClause}
      ORDER BY distance
      LIMIT $2
    `;

    const result = await this.client.query(searchQuery, filterValues);

    return result.rows.map((row) => ({
      id: row.id,
      payload: row.payload,
      score: Math.max(0, Math.min(1, 1 - Number(row.distance))),
    }));
  }

  async get(vectorId: string): Promise<VectorStoreResult | null> {
    const result = await this.client.query(
      `SELECT id, payload FROM ${this.col()} WHERE id = $1`,
      [vectorId],
    );

    if (result.rows.length === 0) return null;

    return {
      id: result.rows[0].id,
      payload: result.rows[0].payload,
    };
  }

  async update(
    vectorId: string,
    vector: number[],
    payload: Record<string, any>,
  ): Promise<void> {
    const vectorStr = `[${vector.join(",")}]`;
    await this.client.query(
      `
      UPDATE ${this.col()}
      SET vector = $1::vector, payload = $2::jsonb
      WHERE id = $3
      `,
      [vectorStr, payload, vectorId],
    );
  }

  async delete(vectorId: string): Promise<void> {
    await this.client.query(`DELETE FROM ${this.col()} WHERE id = $1`, [
      vectorId,
    ]);
  }

  async deleteCol(): Promise<void> {
    await this.client.query(`DROP TABLE IF EXISTS ${this.col()}`);
  }

  private async listCols(): Promise<string[]> {
    const result = await this.client.query(`
      SELECT table_name
      FROM information_schema.tables
      WHERE table_schema = 'public'
    `);
    return result.rows.map((row) => row.table_name);
  }

  async list(
    filters?: SearchFilters,
    topK: number = 100,
  ): Promise<[VectorStoreResult[], number]> {
    const {
      conditions,
      values: filterValues,
      paramIndex,
    } = buildFilterConditions(filters, 1);

    const filterClause =
      conditions.length > 0 ? "WHERE " + conditions.join(" AND ") : "";

    const listQuery = `
      SELECT id, payload
      FROM ${this.col()}
      ${filterClause}
      LIMIT $${paramIndex}
    `;

    const countQuery = `
      SELECT COUNT(*)
      FROM ${this.col()}
      ${filterClause}
    `;

    const listValues = [...filterValues, topK];

    const [listResult, countResult] = await Promise.all([
      this.client.query(listQuery, listValues),
      this.client.query(countQuery, filterValues),
    ]);

    const results = listResult.rows.map((row) => ({
      id: row.id,
      payload: row.payload,
    }));

    return [results, parseInt(countResult.rows[0].count)];
  }

  async close(): Promise<void> {
    await this.client.end();
  }

  async getUserId(): Promise<string> {
    const result = await this.client.query(
      "SELECT user_id FROM memory_migrations LIMIT 1",
    );

    if (result.rows.length > 0) {
      return result.rows[0].user_id;
    }

    // Generate a random user_id if none exists
    const randomUserId =
      Math.random().toString(36).substring(2, 15) +
      Math.random().toString(36).substring(2, 15);
    await this.client.query(
      "INSERT INTO memory_migrations (user_id) VALUES ($1)",
      [randomUserId],
    );
    return randomUserId;
  }

  async setUserId(userId: string): Promise<void> {
    await this.client.query("DELETE FROM memory_migrations");
    await this.client.query(
      "INSERT INTO memory_migrations (user_id) VALUES ($1)",
      [userId],
    );
  }
}
