  "conclusion",
  "introduction",
  "pros",
  "cons",
  "advantages",
  "disadvantages",
]);

/** Markdown/formatting markers to skip during extraction. */
const FORMATTING_MARKERS: Set<string> = new Set([
  "*",
  "-",
  "+",
  "\u2022",
  "\u2013",
  "\u2014",
  "#",
  "##",
  "###",
  "**",
  "__",
]);

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ExtractedEntity {
  type: "PROPER" | "QUOTED" | "COMPOUND" | "NOUN";
  text: string;
}

// ---------------------------------------------------------------------------
// compromise dynamic import
// ---------------------------------------------------------------------------

let nlp: any;
try {
  nlp = require("compromise");
} catch {
  // compromise not installed -- use regex-only fallback
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/** Check for formatting artifacts that indicate non-entity text. */
function hasArtifacts(txt: string): boolean {
  if (txt.includes("**") || txt.includes("__") || txt.includes(":*")) {
    return true;
  }
  if (/\s\*\s|\s\*$|^\*\s/.test(txt)) {
    return true;
  }
  if (txt.includes("  ") || txt.includes("\n") || txt.includes("\t")) {
    return true;
  }
  if (txt.length > 100) {
    return true;
  }
  if (/^[\u2022\-+\u2013\u2014]/.test(txt)) {
    return true;
  }
  return false;
}

/** Strip generic trailing words from a phrase's word list. */
function stripGenericEnding(words: string[]): string[] {
  if (words.length <= 1) {
    return words;
  }
  const last = words[words.length - 1].toLowerCase();
  if (GENERIC_ENDINGS.has(last) && words.length > 2) {
    return words.slice(0, -1);
  }
  return words;
}

/**
 * Determine if a token position is at the start of a sentence.
 * Simple heuristic: index 0, or preceded by sentence-ending punctuation
 * or formatting markers.
 */
function isSentenceStart(
  tokens: string[],
  idx: number,
  rawText: string,
): boolean {
  if (idx === 0) {
    return true;
  }
  const prev = tokens[idx - 1];
  if (/[.!?:]$/.test(prev)) {
    return true;
  }
  if (FORMATTING_MARKERS.has(prev)) {
    return true;
  }
  // Check for newline before this token in the raw text
  const tokenStart = rawText.indexOf(tokens[idx]);
  if (tokenStart > 0 && rawText.charAt(tokenStart - 1) === "\n") {
    return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Extraction strategies
// ---------------------------------------------------------------------------

/** Extract quoted entities via regex. */
function extractQuoted(text: string): ExtractedEntity[] {
  const entities: ExtractedEntity[] = [];

  // Double-quoted
  const doubleQuoteRe = /"([^"]+)"/g;
  let match: RegExpExecArray | null;
  while ((match = doubleQuoteRe.exec(text)) !== null) {
    const inner = match[1].trim();
    if (inner.length > 2) {
      entities.push({ type: "QUOTED", text: inner });
    }
  }

  // Single-quoted (with boundary constraints to avoid apostrophes)
  const singleQuoteRe = /(?:^|[\s([{,;])'([^']+)'(?=[\s.,;:!?)\]]|$)/g;
  while ((match = singleQuoteRe.exec(text)) !== null) {
    const inner = match[1].trim();
    if (inner.length > 2) {
      entities.push({ type: "QUOTED", text: inner });
    }
  }

  return entities;
}

/**
 * Extract proper noun sequences using capitalization heuristics.
 * Finds sequences of capitalized words that are not at sentence starts.
 */
function extractProper(text: string): ExtractedEntity[] {
  const entities: ExtractedEntity[] = [];
  // Tokenize on whitespace, preserving order
  const tokens = text.split(/\s+/).filter(Boolean);
  const functionWords = new Set([
    "'s",
    "of",
    "the",
    "in",
    "and",
    "for",
    "at",
    "is",
  ]);

  let i = 0;
  while (i < tokens.length) {
    const tok = tokens[i];
    // Skip formatting markers
    if (FORMATTING_MARKERS.has(tok)) {
      i++;
      continue;
    }

    const isLabel = i + 1 < tokens.length && tokens[i + 1] === ":";
    const isCap =
      tok.length > 0 &&
      tok.charAt(0) === tok.charAt(0).toUpperCase() &&
      /[A-Z]/.test(tok.charAt(0));

    if (isCap && !isLabel) {
      const seq: Array<{ token: string; idx: number }> = [
        { token: tok, idx: i },
      ];
      let j = i + 1;
      while (j < tokens.length) {
        const t = tokens[j];
        const tIsCap =
          t.length > 0 &&
          t.charAt(0) === t.charAt(0).toUpperCase() &&
          /[A-Z]/.test(t.charAt(0));
        if (tIsCap || functionWords.has(t.toLowerCase())) {
          seq.push({ token: t, idx: j });
          j++;
        } else {
          break;
        }
      }

      // Strip trailing function words
      while (
        seq.length > 0 &&
        functionWords.has(seq[seq.length - 1].token.toLowerCase())
      ) {
        seq.pop();
      }

      if (seq.length > 0) {
        // Check for at least one mid-sentence capitalized word
        const hasMidCap = seq.some(({ token, idx: tokenIdx }) => {
          const isCapWord =
            /[A-Z]/.test(token.charAt(0)) &&
            !functionWords.has(token.toLowerCase());
          return isCapWord && !isSentenceStart(tokens, tokenIdx, text);
        });

        if (hasMidCap) {
          const phrase = seq.map((s) => s.token).join(" ");
          if (phrase.length > 2) {
            entities.push({ type: "PROPER", text: phrase });
          }
        }
      }
      i = j;
    } else {
      i++;
    }
  }

  return entities;
}

/**
 * Extract compound noun phrases using the `compromise` NLP library.
 * Returns COMPOUND and NOUN entities derived from noun chunks.
 */
function extractCompoundsWithNlp(text: string): ExtractedEntity[] {
  if (!nlp) {
    return [];
  }

  const entities: ExtractedEntity[] = [];
  const doc = nlp(text);
  const nouns = doc.nouns().out("array") as string[];

  for (const nounPhrase of nouns) {
    const trimmed = nounPhrase.trim();
    if (!trimmed || trimmed.length <= 3) {
      continue;
    }

    const words = trimmed.split(/\s+/);
    if (words.length < 2) {
      continue;
    }

    // Filter out phrases where the head is generic
    const head = words[words.length - 1].toLowerCase();
    if (GENERIC_HEADS.has(head)) {
      // Check if there's a specific modifier
      const hasSpecificMod = words.some(
        (w) =>
          !NON_SPECIFIC_ADJ.has(w.toLowerCase()) &&
          w !== words[words.length - 1],
      );
      if (!hasSpecificMod) {
        continue;
      }
    }

    // Filter non-specific adjectives from the beginning
    const filtered = words.filter(
      (w) => !NON_SPECIFIC_ADJ.has(w.toLowerCase()),
    );
    const cleaned = stripGenericEnding(filtered);

    if (cleaned.length >= 2) {
      const phrase = cleaned.join(" ");
      if (phrase.length > 3) {
        entities.push({ type: "COMPOUND", text: phrase });
      }
    }
  }

  return entities;
}

/**
 * Regex-only fallback for compound extraction when compromise is not available.
 * Finds multi-word capitalized sequences and common compound patterns.
 */
function extractCompoundsRegex(text: string): ExtractedEntity[] {
  const entities: ExtractedEntity[] = [];

  // Multi-word sequences with at least one non-trivial word
  // Match sequences like "machine learning", "New York", "data science"
  const compoundRe =
    /\b([A-Z][a-z]+(?:\s+(?:of|and|the|for|in)\s+)?[A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)\b/g;
  let match: RegExpExecArray | null;
  while ((match = compoundRe.exec(text)) !== null) {
    const phrase = match[1].trim();
    if (phrase.length > 3 && phrase.includes(" ")) {
      const words = phrase.split(/\s+/);
      const head = words[words.length - 1].toLowerCase();
      if (!GENERIC_HEADS.has(head)) {
        const filtered = words.filter(
          (w) => !NON_SPECIFIC_ADJ.has(w.toLowerCase()),
        );
        const cleaned = stripGenericEnding(filtered);
        if (cleaned.length >= 2) {
          entities.push({ type: "COMPOUND", text: cleaned.join(" ") });
        }
      }
    }
  }

  // Also try lowercase compound patterns (e.g., "machine learning", "deep learning")
  const lowerCompoundRe = /\b([a-z]+(?:\s+[a-z]+){1,3})\b/g;
  while ((match = lowerCompoundRe.exec(text)) !== null) {
    const phrase = match[1].trim();
    const words = phrase.split(/\s+/);
    if (words.length >= 2 && words.length <= 4 && phrase.length > 5) {
      const head = words[words.length - 1].toLowerCase();
      const allGeneric = words.every(
        (w) =>
          NON_SPECIFIC_ADJ.has(w.toLowerCase()) ||
          GENERIC_HEADS.has(w.toLowerCase()),
      );
      if (!allGeneric && !GENERIC_HEADS.has(head)) {
        // Only include if it looks like a meaningful compound
        const hasContentWord = words.some(
          (w) =>
            !NON_SPECIFIC_ADJ.has(w.toLowerCase()) &&
            !GENERIC_HEADS.has(w.toLowerCase()) &&
            w.length > 2,
        );
        if (hasContentWord) {
          const filtered = words.filter(
            (w) => !NON_SPECIFIC_ADJ.has(w.toLowerCase()),
          );
          const cleaned = stripGenericEnding(filtered);
          if (cleaned.length >= 2) {
            entities.push({ type: "COMPOUND", text: cleaned.join(" ") });
          }
        }
      }
    }
  }

  return entities;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract named entities, quoted text, and noun compounds from text.
 *
 * Uses `compromise` for NLP-based noun phrase extraction when available,
 * falling back to regex-only heuristics otherwise.
 *
 * Entity types (in priority order for deduplication):
 *   PROPER   - Capitalized multi-word sequences not at sentence start
 *   COMPOUND - Multi-word noun phrases with specific modifiers
 *   QUOTED   - Text in single or double quotes (min 3 chars)
 *   NOUN     - Single nouns from circumstantial patterns
 *
 * @param text - Input text to extract entities from.
 * @returns Deduplicated list of extracted entities.
 */
export function extractEntities(text: string): ExtractedEntity[] {
  const raw: ExtractedEntity[] = [];

  // 1. QUOTED entities (always regex)
  raw.push(...extractQuoted(text));

  // 2. PROPER entities (capitalization heuristics)
  raw.push(...extractProper(text));

  // 3. COMPOUND entities (NLP or regex fallback)
  if (nlp) {
    raw.push(...extractCompoundsWithNlp(text));
  } else {
    raw.push(...extractCompoundsRegex(text));
  }

  // === DEDUPLICATION & CLEANUP ===

  // First pass: deduplicate by lowercase text
  const seen = new Set<string>();
  const deduped: ExtractedEntity[] = [];
  for (const entity of raw) {
    const key = entity.text.toLowerCase().trim();
    if (key.length > 2 && !seen.has(key)) {
      seen.add(key);
      deduped.push(entity);
    }
  }

  // Clean up formatting artifacts
  const cleaned: ExtractedEntity[] = [];
  for (const entity of deduped) {
    let txt = entity.text.trim();
    // Strip leading/trailing asterisks
    txt = txt.replace(/^\*+\s*|\s*\*+$/g, "");
    // Strip trailing colons
    txt = txt.replace(/\s*:+$/, "");
    // Strip leading numbered list markers
    txt = txt.replace(/^\d+\s*\.\s*/, "");
    // Strip trailing sentence punctuation (".", ",", ";", "!", "?") — otherwise
    // "Paris." and "Paris" produce different embeddings and break entity dedup.
    txt = txt.replace(/[.,;!?]+$/, "").trim();

    if (!txt || txt.length <= 2 || hasArtifacts(txt)) {
      continue;
    }

    // Filter generic single-word PROPER nouns
    if (
      entity.type === "PROPER" &&
      !txt.includes(" ") &&
      GENERIC_CAPS.has(txt.toLowerCase())
    ) {
      continue;
    }

    cleaned.push({ type: entity.type, text: txt });
  }

  // Keep best type per entity (PROPER > COMPOUND > QUOTED > NOUN)
  const typePriority: Record<string, number> = {
    PROPER: 0,
    COMPOUND: 1,
    QUOTED: 2,
    NOUN: 3,
  };
  const best = new Map<string, ExtractedEntity>();
  for (const entity of cleaned) {
    const key = entity.text.toLowerCase();
    const existing = best.get(key);
    if (
      !existing ||
      (typePriority[entity.type] ?? 99) < (typePriority[existing.type] ?? 99)
    ) {
      best.set(key, entity);
    }
  }
  const bestEntities = Array.from(best.values());

  // Remove entities that are substrings of longer entities
  const allLower = bestEntities.map((e) => e.text.toLowerCase());
  return bestEntities.filter(
    (entity) =>
      !allLower.some(
        (other) =>
          entity.text.toLowerCase() !== other &&
          other.includes(entity.text.toLowerCase()),
      ),
  );
}

/**
 * Extract entities from multiple texts.
 *
 * @param texts - List of input texts to extract entities from.
 * @returns List of entity lists, one per input text.
 */
export function extractEntitiesBatch(texts: string[]): ExtractedEntity[][] {
  return texts.map(extractEntities);
}
","/**
 * Scoring utilities for hybrid retrieval.
 *
 * Provides:
 * - BM25 normalization: Sigmoid normalization of raw BM25 scores to [0, 1].
 * - BM25 parameter selection: Query-length-adaptive sigmoid parameters.
 * - Additive scoring: Combined scoring with semantic + BM25 + entity boost.
 */

export const ENTITY_BOOST_WEIGHT = 0.5;

/**
 * Get BM25 sigmoid parameters based on query length.
 *
 * Longer queries tend to have higher raw BM25 scores, so we adjust
 * the sigmoid midpoint and steepness accordingly.
 *
 * @param query - The original query string.
 * @param lemmatized - Optional pre-lemmatized query string. If not provided,
 *   the term count is estimated from the raw query.
 * @returns A tuple of [midpoint, steepness] for sigmoid normalization.
 */
export function getBm25Params(
  query: string,
  lemmatized?: string,
): [number, number] {
  const text = lemmatized ?? query;
  const numTerms = text.trim().split(/\s+/).filter(Boolean).length || 1;

  if (numTerms <= 3) {
    return [5.0, 0.7];
  } else if (numTerms <= 6) {
    return [7.0, 0.6];
  } else if (numTerms <= 9) {
    return [9.0, 0.5];
  } else if (numTerms <= 15) {
    return [10.0, 0.5];
  } else {
    return [12.0, 0.5];
  }
}

/**
 * Normalize a raw BM25 score to [0, 1] using logistic sigmoid.
 *
 * @param rawScore - Raw BM25 score (unbounded, typically 0-20+).
 * @param midpoint - Score at which sigmoid outputs 0.5.
 * @param steepness - Controls how quickly sigmoid transitions.
 * @returns Normalized score in range [0, 1].
 */
export function normalizeBm25(
  rawScore: number,
  midpoint: number,
  steepness: number,
): number {
  return 1.0 / (1.0 + Math.exp(-steepness * (rawScore - midpoint)));
}

export interface ScoredResult {
  id: string;
  score: number;
  payload: Record<string, any>;
}

/**
 * Score candidates additively and return top-k results.
 *
 * For each candidate:
 *   combined = (semantic + bm25 + entity_boost) / max_possible
 *
 * Threshold gates the semantic score BEFORE combining -- candidates
 * below the threshold are excluded even if BM25/entity would boost them.
 *
 * The divisor adapts based on which signals are active:
 *   - Semantic only: max_possible = 1.0
 *   - Semantic + BM25: max_possible = 2.0
 *   - Semantic + BM25 + entity: max_possible = 2.5
 *   - Semantic + entity (no BM25): max_possible = 1.5
 *
 * @param semanticResults - Candidate results with id, score, and payload.
 * @param bm25Scores - Map of memory ID to normalized BM25 score.
 * @param entityBoosts - Map of memory ID to entity boost score.
 * @param threshold - Minimum semantic score to include a candidate.
 * @param topK - Maximum number of results to return.
 * @returns Sorted list of scored results, highest score first.
 */
export function scoreAndRank(
  semanticResults: Array<{
    id: string;
    score: number;
    payload: Record<string, any>;
  }>,
  bm25Scores: Record<string, number>,
  entityBoosts: Record<string, number>,
  threshold: number,
  topK: number,
): ScoredResult[] {
  const hasBm25 = Object.keys(bm25Scores).length > 0;
  const hasEntity = Object.keys(entityBoosts).length > 0;

  let maxPossible = 1.0;
  if (hasBm25) {
    maxPossible += 1.0;
  }
  if (hasEntity) {
    maxPossible += ENTITY_BOOST_WEIGHT;
  }

  const scored: ScoredResult[] = [];

  for (const result of semanticResults) {
    const memId = result.id;
    if (memId == null) {
      continue;
    }

    const semanticScore = result.score ?? 0.0;
    if (semanticScore < threshold) {
      continue;
    }

    const memIdStr = String(memId);
    const bm25Score = bm25Scores[memIdStr] ?? 0.0;
    const entityBoost = entityBoosts[memIdStr] ?? 0.0;

    const rawCombined = semanticScore + bm25Score + entityBoost;
    const combined = Math.min(rawCombined / maxPossible, 1.0);

    scored.push({
      id: memIdStr,
      score: combined,
      payload: result.payload,
    });
  }

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, topK);
}
","/**
 * Best-effort read/write of ~/.mem0/config.json from the TS SDK.
 *
 * Used to stitch PostHog identities: SDKs and CLIs persist anonymous
 * distinct_id values here, and the TS MemoryClient reads those on init to
 * fire $identify and merge them into the email identity.
 *
 * Node-only. Browsers (no `process.versions.node`) no-op.
 */

export interface Mem0AnonIds {
  oss?: string;
  cli?: string;
  aliasedPairs: string[];
}

interface NodeFs {
  fs: typeof import("fs");
  path: typeof import("path");
  crypto: typeof import("crypto");
  configPath: string;
}

async function getNodeFs(): Promise<NodeFs | null> {
  if (typeof process === "undefined" || !process.versions?.node) return null;
  try {
    const [fs, path, os, crypto] = await Promise.all([
      import("fs"),
      import("path"),
      import("os"),
      import("crypto"),
    ]);
    const fsMod = (fs as any).default ?? fs;
    const pathMod = (path as any).default ?? path;
    const osMod = (os as any).default ?? os;
    const cryptoMod = (crypto as any).default ?? crypto;
    const dir = process.env.MEM0_DIR || pathMod.join(osMod.homedir(), ".mem0");
    return {
      fs: fsMod,
      path: pathMod,
      crypto: cryptoMod,
      configPath: pathMod.join(dir, "config.json"),
    };
  } catch {
    return null;
  }
}

function loadConfig(node: NodeFs): Record<string, any> | null {
  try {
    if (!node.fs.existsSync(node.configPath)) return null;
    const parsed = JSON.parse(node.fs.readFileSync(node.configPath, "utf8"));
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function writeConfig(node: NodeFs, config: Record<string, any>): void {
  node.fs.mkdirSync(node.path.dirname(node.configPath), { recursive: true });
  node.fs.writeFileSync(node.configPath, JSON.stringify(config, null, 4));
}

function aliasPairMarker(node: NodeFs, anonId: string, email: string): string {
  return node.crypto
    .createHash("sha256")
    .update(`${anonId}\0${email}`, "utf8")
    .digest("hex");
}

function randomUserId(node: NodeFs): string {
  if (typeof node.crypto.randomUUID === "function") {
    return node.crypto.randomUUID();
  }
  return (
    Math.random().toString(36).substring(2, 15) +
    Math.random().toString(36).substring(2, 15)
  );
}

export async function getOrCreateMem0UserId(): Promise<string | null> {
  const node = await getNodeFs();
  if (!node) return null;
  try {
    const config = loadConfig(node) ?? {};
    if (typeof config.user_id === "string" && config.user_id) {
      return config.user_id;
    }
    const userId = randomUserId(node);
    config.user_id = userId;
    writeConfig(node, config);
    return userId;
  } catch {
    return null;
  }
}

export async function readMem0AnonIds(): Promise<Mem0AnonIds | null> {
  const node = await getNodeFs();
  if (!node) return null;
  const config = loadConfig(node);
  if (!config) return null;
  const telemetry =
    config.telemetry && typeof config.telemetry === "object"
      ? config.telemetry
      : {};
  return {
    oss: typeof config.user_id === "string" ? config.user_id : undefined,
    cli:
      typeof telemetry.anonymous_id === "string"
        ? telemetry.anonymous_id
        : undefined,
    aliasedPairs: Array.isArray(telemetry.aliased_pairs)
      ? telemetry.aliased_pairs.filter(
          (item: unknown) => typeof item === "string",
        )
      : [],
  };
}

export async function isMem0Aliased(
  anonId: string,
  email: string,
): Promise<boolean> {
  if (!anonId || !email) return false;
  const node = await getNodeFs();
  if (!node) return false;
  const config = loadConfig(node);
  if (!config) return false;
  const telemetry =
    config.telemetry && typeof config.telemetry === "object"
      ? config.telemetry
      : {};
  const aliasedPairs = Array.isArray(telemetry.aliased_pairs)
    ? telemetry.aliased_pairs
    : [];
  return aliasedPairs.includes(aliasPairMarker(node, anonId, email));
}

export async function markMem0Aliased(
  anonId: string,
  email: string,
): Promise<void> {
  const node = await getNodeFs();
  if (!node) return;
  try {
    const config = loadConfig(node) ?? {};
    const telemetry =
      config.telemetry && typeof config.telemetry === "object"
        ? config.telemetry
        : {};
    const aliasedPairs = Array.isArray(telemetry.aliased_pairs)
      ? telemetry.aliased_pairs
      : [];
    const marker = aliasPairMarker(node, anonId, email);
    if (!aliasedPairs.includes(marker)) {
      aliasedPairs.push(marker);
    }
    telemetry.aliased_pairs = aliasedPairs;
    config.telemetry = telemetry;
    writeConfig(node, config);
  } catch {
    // Best-effort: read-only filesystems and unwritable paths just skip.
