  } else if (w.endsWith("ness")) {
    w = w.slice(0, -4);
  } else if (w.endsWith("ment") && w.length > 5) {
    w = w.slice(0, -4);
  } else if (w.endsWith("ation") && w.length > 6) {
    w = w.slice(0, -5) + "e";
  } else if (w.endsWith("ting") && w.length > 5) {
    w = w.slice(0, -3);
  } else if (w.endsWith("ing") && w.length > 5) {
