  if (!node) return false;
  const config = loadConfig(node);
  if (!config) return false;
  const telemetry =
    config.telemetry && typeof config.telemetry === "object"
      ? config.telemetry
      : {};
  const aliasedPairs = Array.isArray(telemetry.aliased_pairs)
